def validate_all(record):
    errors = []
    if not isinstance(record.get("name"), str) or not record["name"]:
        errors.append(ValueError("name is required"))
    age = record.get("age")
    if not isinstance(age, int):
        errors.append(TypeError("age must be an int"))
    elif age < 0:
        errors.append(ValueError("age must be >= 0"))
    if "@" not in str(record.get("email", "")):
        errors.append(ValueError("email must contain @"))
    if errors:
        raise ExceptionGroup("invalid record", errors)

try:
    validate_all({"name": "", "age": -3, "email": "x"})
except ExceptionGroup as eg:
    print(eg.message, len(eg.exceptions))
    for e in eg.exceptions:
        print(type(e).__name__, e)

def count_by_type(group):
    counts = {"ValueError": 0, "TypeError": 0}
    try:
        raise group
    except* ValueError as vg:
        counts["ValueError"] = len(vg.exceptions)
    except* TypeError as tg:
        counts["TypeError"] = len(tg.exceptions)
    return counts

group = ExceptionGroup("mixed", [ValueError("a"), ValueError("b"), TypeError("c")])
print(count_by_type(group))
